SET @manifesto += N'[{"id":"observacao-documental-1tri-2026-ind-01","indicadorId":"1","lancamentoId":"3","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"O resultado evidencia a efetividade das ações de segmentação e personalização, bem como a evolução da capacidade analítica e operacional para ativação qualificada da base de clientes. Foram realizadas campanhas via push2, com foco na divulgação de concursos acumulados, modalidades de jogos, funcionalidades do App Loterias, jogos individuais e bolões, aniversários de clientes, feriados locais e promoção de jogo responsável. Foram alcançados 1.241.587 clientes, de uma base de 2.773.599 clientes, representando 44,76% do realizado e 447,64% do atingindo da meta.\n\n2 Uma campanha por meio de push (ou notificação push) é uma estratégia de marketing direto que consiste no envio de mensagens curtas e clicáveis diretamente para a tela do celular, tablet ou navegador de desktop do usuário.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"7","sha256Observacao":"efc678e31f01c2426e60df44cf2049c65686f708d4da0bb8d4cd87493abb0980","sha256ObservacaoSqlUtf16":"c408e39d72ce19ea53f3f1044f947f788d8808423a242c85e2af59b9826e2920","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-02","indicadorId":"2","lancamentoId":"15","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"Considerando a fórmula e meta estabelecida para o indicador, a meta anual é prevista é a nota de 58. A nota é calculada considerando a pesquisa NPS baseline de 55 pontos e a meta de 2026 para redução de 20% do gap em relação à nota de referência 70, resultado em 58.\n\nNesse sentido, a mensuração do indicador está prevista para o final do ano de 2026, sendo que ao longo do exercício serão realizadas ações de melhorias junto aos clientes, acompanhadas pelo Indicador Aprimoramento da experiência do cliente – previsto no Plano de Negócios de 2026.\n\n* Considerando a baseline de 55 pontos e a diretriz de redução de 20% do gap em relação à nota de referência 70, a meta correta para 2026 corresponde a NPS igual a 58, registra-se a intenção de submeter Proposição específica ao Conselho de Administração o ajuste material do valor, de modo a preservar a coerência metodológica e a consistência da série histórica do indicador.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"8","sha256Observacao":"5e570f1024db6345b0fef569fee3a4bef79ed022d5bcc2a9b00c96dec0ddaafa","';
SET @manifesto += N'sha256ObservacaoSqlUtf16":"da8dcca4a5072702077cc08386e12102343cf7afd3e0de90acd45bb652233cac","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-03","indicadorId":"3","lancamentoId":"27","versaoLancamento":2,"statusEsperado":"Enviado para homologacao","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"Em março, a quantidade média mensal de clientes ativos foi de 2.982.989 (jan a mar/2026), representando um aumento de 74,41%, em comparação quantidade média mensal de clientes ativos no ano anterior, de 1.710.374 (jan a mar/2025), resultando em 265,73% como atingimento da meta do período.\n\nO resultado do indicador evidencia o sucesso das ações de aquisição, reativação e engajamento de clientes, além do impacto positivo das iniciativas de digitalização e personalização da jornada.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"9","sha256Observacao":"defb84f453f2542397c4c40f73b3f1287fbc9b602e1cb911b4e2a59f57fda3c9","sha256ObservacaoSqlUtf16":"1ea057dbbb0a01c664405b8946a443e59f6757b7b6ec1a4d3df9233039ae428d","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-04","indicadorId":"4","lancamentoId":"39","versaoLancamento":2,"statusEsperado":"Em preenchimento","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"A partir da realização da pesquisa NPS de baseline de 2025, foram definidas 22 melhorias como plano de trabalho ao longo do ano de 2026, em que para atingimento da meta anual do indicador para o ano é necessária a entrega de ao menos 06 melhorias, representando assim a meta de 25% das ocorrências apontadas.\n\nAs melhorias mapeadas demandam implantação junto à área de TI da CAIXA.\n\nNesse sentido, a curva definida para o ano foi estruturada trimestralmente da seguinte forma:\n▪ 1TRI26: 4,54% - entrega de 01 melhoria do plano de trabalho de 2026;\n▪ 2TRI26: 13,64% - entrega de 03 melhorias (acumuladas) do plano de trabalho de 2026;\n▪ 3TRI26: 18,18% - entrega de 04 melhorias (acumuladas) do plano de trabalho de 2026;\n▪ 4TRI26: 253% - entrega de 06 melhorias (acumuladas) do plano de trabalho de 2026.\n\nNo 1º trimestre foi implementada 01 melhoria, representando 113,64% de atingimento da meta, que se refere envio de campanhas via push ';
SET @manifesto += N'aos clientes, atendendo às reclamações de clientes indicando a necessidade de envio de mensagens educativas, atendendo aos princípios e diretrizes do Programa Jogo Responsável.\n\n3 O plano de trabalho previsto para atendimento desse indicador considera o escopo de 22 melhorias mapeadas posteriormente à definição da meta do presente indicador, conforme data da aprovação do PN 2026 da CAIXA Loterias.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"10","sha256Observacao":"586a42301b2cb0d4b3be66a6fca239d43f9b244701389c8816749c157a904a4b","sha256ObservacaoSqlUtf16":"0a339230532ac6a4f47a5febf278387142cc0b0f6588a73f5cd2433787858786","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-05","indicadorId":"5","lancamentoId":"51","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"A meta estabelecida para o período considerou a projeção orçamentária prevista no orçamento da Companhia.\n\nNo que se refere à descrição e meta do indicador, registra-se que será submetida proposta ao Conselho de Administração para revisão do indicador, a fim de garantir sua aderência ao orçamento da Companhia vigente, com a exclusão da previsão da projeção inclui Apostas de Quota Fixa.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"11","sha256Observacao":"431240dbe74572c61e742778eebe1081f1980906f1783341288495aa8f5d0e7e","sha256ObservacaoSqlUtf16":"d72a7406d879fc9eb02332bc06fd234e3788ef232b2dff700b1b1f8ba7c47f33","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-06","indicadorId":"6","lancamentoId":"63","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"Em janeiro/26 a companhia obteve lucro líquido de R$ 119,4 milhões, receita total de R$ 223,6 milhões e nosso Indice de Eficiência Operacional atingiu 6,42%. Em fevereiro/26 a companhia obteve lucro líquido de R$ 222,0 milhões, receita total de R$ 438,9 milhões e nosso Indice de Eficiência Operacional atingiu 11,00%. Em março/26 a companhia obteve lucro líquido de R$ 336,3 milhões, receita total de R$ 663,2 milhões e nosso Indice de Eficiência Operacional atingiu 10,80%.","fonteDocumental":"';
SET @manifesto += N'Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"11","sha256Observacao":"98b53caabb1b440eafc06b713bdd8aaf1f0e6d49a9c3bd4b7592eab507b1d53b","sha256ObservacaoSqlUtf16":"246561240af7d1d942629a636291b8445e00c4c147ca67d93f4987057f1fd4fc","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-07","indicadorId":"7","lancamentoId":"75","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"A meta estabelecida para o período considerou a projeção orçamentária prevista no orçamento da Companhia.\n\nEm janeiro/26 a Companhia obteve lucro líquido de R$ 119,4 milhões, receita total de R$ 223,6 milhões e nosso Indice de Eficiência Operacional atingiu 6,42%\n\nEm fevereiro/26 a Companhia obteve lucro líquido de R$ 222,0 milhões, receitas totais de R$ 438,9 milhões e despesas totais de R$ 216,9. Já no mês de março, o lucro líquido foi de R$ 336,3 milhões, receita total de R$ 663,2 milhões e despesas de R$ 326,3.\n\nNo que se refere à meta anual estabelecida para o indicador, registra-se a intenção de submeter Proposição específica ao Conselho de Administração a atualização do indicador a fim de garantir a coerência metodológica e as projeções consideradas no PDG vigente.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"12","sha256Observacao":"c1465a99910f45b2f211810aba68a5e5033dfc05a75ba8ddec99910ad80c4087","sha256ObservacaoSqlUtf16":"c24e8ea18199703d05cd5f8b95aa984b8266f7b3dd2182818d5b9532a344d951","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-08","indicadorId":"8","lancamentoId":"87","versaoLancamento":2,"statusEsperado":"Retificado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"A partir da meta estabelecida de aumentar em 5 pontos percentuais para o ano de 2026, a meta do 1TRI26 foi de 28,05%, considerando o percentual de 23,05% de 2025 acrescido de 05 p.p.\nA arrecadação total no 1TRI/2025 foi de R$ 5.504,9 milhões e a arrecadação em canais eletrônicos foi de R$ 1.268,7 milhões, no mesmo período.\nJá no período 1TRI26, os dados realizados registraram a participação dos canais digitais em R$ 1.770,2 milhões, frente à arrecadação em canal físico de R$ 5.966,9 milhões, representando aumento ';
SET @manifesto += N'de 29,67 p.p. em comparação ao ano anterior e 105,8% de atingimento da meta.\nO resultado reforça a maturidade das iniciativas digitais, a maior adesão dos clientes aos canais eletrônicos e a efetividade das estratégias de estímulo à migração digital.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"13","sha256Observacao":"e08651fac5ab90b1583c9239984446d1c40bb35f4b38bdc87eb513c8bace868e","sha256ObservacaoSqlUtf16":"0aca99c06abb0a6255dcac6381396f266a21029c3566cc28ccaee4efdbba63c9","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-09","indicadorId":"9","lancamentoId":"99","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"A base de dados referente à arrecadação nos canais eletrônicos, para apuração do indicador de vendas com PIX, não considera dados do Internet Banking CAIXA – IBC, tendo em vista que esse meio de pagamento não é aceito no IBC.\n\nA seguinte curva de meta foi definida para 2026:\n▪ 1TRI26: 61%;\n▪ 2TRI26: 62%;\n▪ 3TRI26: 63%;\n▪ 4TRI26: 65%.\n\nA meta estabelecida para o período considerou a projeção orçamentária prevista no Plano de Dispêndios Globais de 2026 da Companhia.\n\nAo final do 1 TRI26, o realizado foi de R$ 1,127 bilhão de vendas com PIX, representando 67% das vendas nos canais eletrônicos, que registrou R$ 1.686,1 no total de arrecadação.\nNo mesmo período de 2025, os dados de vendas com PIX foi de R$ 620,8 milhões, representando 56% das vendas nos canais eletrônicos, que registrou R$ 1.114,2 milhões no total de arrecadação.\nConsiderando a meta de aumentar em 05 p.p. as vendas com o meio de pagamento Pix no canal eletrônico, o resultado representa 110,09% de atingimento da meta.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"13, 14","sha256Observacao":"65326c74fd3124c938c0da741f8231764c404b803eda97157897a24445295190","sha256ObservacaoSqlUtf16":"904d1ce5068f8a7d7922cb7bc19080bf875a699cadc40c10b82122e94223b165","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-10","indicadorId":"10","lancamentoId":"111","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"Inicialmente, cabe m';
SET @manifesto += N'encionar as metas previstas ao longo dos períodos do PEI 2026-2030 da CAIXA Loterias para este indicador:\n\n▪ Ano 2026: Piloto ou MVP (Mínimo Produto Viável) da Plataforma de Jogos;\n▪ Ano 2027: Implementação baseline de Participação de Mercado;\n▪ Ano 2028: Estar entre as 05 maiores plataformas do ecossistema de jogos e apostas no Brasil;\n▪ Ano 2029: Estar entre as 03 maiores plataformas do ecossistema de jogos e apostas no Brasil;\n▪ Ano 2030: Ser a maior plataforma do ecossistema de jogos do Brasil.\n\nA meta do indicador para 2026 é o Piloto ou MVP (Mínimo Produto Viável) da Plataforma de Jogos, não havendo meta para o 1TRI26.\n\nAo longo do 1 TRI26, foram realizadas ações para execução do projeto, como alocação de equipe do projeto, agenda de abertura (Kickoff), execução de dois ciclos de reuniões do projeto (sprints), contemplando o início dos trabalhos para definição da arquitetura do sistema, processos e ferramentas, criação do ambiente tecnológico, concessão de acessos, definição negocial da funcionalidade de cadastro de canais de venda de loterias.\n\nNo que se refere à fórmula e descrição adotados para o presente indicador, registra-se a intenção de submeter Proposição específica ao Conselho de Administração propondo que a redação da descrição e fórmula sejam revisados. Além disso, até o momento, não foram identificados dados oficiais divulgados relacionados ao GGR de mercado.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"14, 15","sha256Observacao":"2670696ae41edc6074a4f363c70c3f0fce15dd8224ced8af82b27fd7e7f45b5b","sha256ObservacaoSqlUtf16":"fb86ae38b8e1d6f8d5357df1af026a7ca88ea7c148e353cc02c441e0bbc50377","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-11","indicadorId":"11","lancamentoId":"123","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"A seguinte curva de meta foi definida para 2026 com relação ao presente indicador:\n\n▪ 1TRI26: 35% - Realização de Consulta Pública de Informações - RFI (Request for Information);\n▪ 2TRI26: 70% - Realização de Consulta Pública de Propostas - RFP (Request for Proposal);\n▪ 3TRI26: 85% - Iniciação da Fase Seleção;\n▪ 4TRI26: 100% - Contrato assinado com fornecedor.\n\nComo evidência do realizado ao longo do 1TRI26, foi iniciado rito de contratação de solução para o projeto Carteira Digital, em que foi realizada a definição de escopo para construção de Termo de Referência (TR) e publicação de Consulta Pública de Informações – Request For Information (RFI).","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginas';
SET @manifesto += N'Documento":"15, 16","sha256Observacao":"477b39fd3ead6a0baf6d7644b4479523c007a50919cba6916389a38168650e39","sha256ObservacaoSqlUtf16":"6b8265ca4dfe2c211204df47628937f94aa2b5d4a7339bdab08b52ab0e7ce0b4","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-12","indicadorId":"12","lancamentoId":"135","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"Divulgação para os gestores, dos resultados da Pesquisa de Clima Organizacional referente ao exercício de 2025, promovendo o conhecimento e a transparência quanto à percepção dos empregados. A partir da análise dos resultados, foram identificados e priorizados os principais pontos de atenção e temas estratégicos a serem desenvolvidos ao longo do ano de 2026, alinhados às diretrizes institucionais de fortalecimento do clima organizacional. Ainda no mês de janeiro de 2026, foi definida a composição do grupo de empregados que atuarão diretamente na construção e detalhamento do plano de ação para o ciclo de 2026.\n\nAdemais, foi realizado o Workshop Plano de Ação CAIXA Loterias, conduzida pela GPTW, responsável pela Pesquisa de Clima Organizacional 2025 e pelo apoio metodológico ao ciclo de 2026. Durante o encontro, foram identificadas oportunidades de melhorias, definição dos planos de ação a serem desenvolvidos com desdobramento por equipes, garantindo representatividade, engajamento e estabelecimento de responsabilidades.\n\nAs ações desenvolvidas ao longo dos meses têm como objetivo atingir a meta, cuja efetividade será avaliada após a realização de nova pesquisa a ser efetuada em novembro/2026.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"16","sha256Observacao":"a28ff7d7ba2858612a62388bd9839fe2addd2179b48c6f9984a72416cc90396e","sha256ObservacaoSqlUtf16":"68c701e50bb98dc0f68c414473da18cc7a65271552fc635d5dada6c7994e3d61","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-13","indicadorId":"13","lancamentoId":"147","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"No mês de março/26 tivemos a proporção de 16 gestoras do sexo feminino (04 mulheres chefes de unidade + 12 mulheres com função ge';
SET @manifesto += N'rencial) por 43 gestores de ambos os sexos (12 chefes de unidade + 31 funções gerenciais). Para o alcance da meta, seriam necessários, no mínimo, 19 gestoras do sexo feminino dentre 43 de ambos os sexos.\n\nTipo de Função Gratificada por Gênero:\n\nFonte: https://infopessoas.caixa/infopessoas/genero_tipo_fg.asp\n\nNo que se refere à meta adotada, registra-se a intenção de submeter Proposição específica ao Conselho de Administração propondo que a redação da meta passe a ser: “Alcançar a média mensal de, no mínimo, 42,5% de mulheres gestoras na CAIXA Loterias, alcançando o valor atual da CAIXA (out/25)”.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"17","sha256Observacao":"769c63699e06498ed88a304c80362b0e32771a47beffd0ca3137882afb88d524","sha256ObservacaoSqlUtf16":"9d2b5457fd7dee1bb0752a7611fe6ea6769e6c28c3c8159690e4576a7da73e03","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-14","indicadorId":"14","lancamentoId":"159","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"No mês de março/26 tivemos a proporção de 11 gestores declarados dentre os 43 gestores totais. Para o alcance da meta, seriam necessários, no mínimo, 16 gestores declarados dentre 43 gestores totais.\n\nTipo de Função Gratificada por Raça/Cor:\n\nFonte: https://infopessoas.caixa/infopessoas/genero_tipo_fg.asp\n\nTipo de Deficiência por Tipo de Função:\n\nFonte: https://infopessoas.caixa/infopessoas/genero_tipo_fg.asp\n\nNo que se refere à meta adotada, registra-se a intenção de submeter Proposição específica ao Conselho de Administração propondo que a redação da meta passe a ser: “Alcançar a média mensal de, no mínimo, 35% de empregados negros, amarelos, pardos ou indígenas e/ou PcD como gestores”.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"18","sha256Observacao":"7b54201a0383d13cdd1499a9c4cf2d1e0a4e3ec17e05e2ee2a9a514e567ddf3a","sha256ObservacaoSqlUtf16":"4ac4e3c93064a8ba8401158029022317d05daa58869d4e748d1f94c55f725422","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-15","indicadorId":"15","lancamentoId":"171","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_IN';
SET @manifesto += N'FORME_TRIMESTRAL","observacao":"A seguinte curva de meta foi definida para 2026, considerando a Trilha de Desenvolvimento específica da CAIXA Loterias ainda em desenvolvimento:\n\n1TRI26: 90% do público-alvo com 01 curso “Curso de Jogo Responsável” concluído.\n2TR26: 90% do público-alvo com 02 cursos concluídos (acumulado) – Em elaboração\n3TRI26: 90% do público-alvo com 04 cursos concluídos (acumulado) – Em elaboração\n4TRI26: 90% do público-alvo com 05 cursos concluídos (acumulado) – Em elaboração\n\nFoi apurado que 137 funcionários, de 151 (90,7%), realizaram uma ação de disseminação de Jogo Responsável (JR) até MAR 2026, na Universidade CAIXA.\n\nFoi iniciado o desenvolvimento das Vitrines6 das Unidades da CAIXA Loterias a fim de direcionar a elaboração da Trilha de Capacitação específica para os empregados da Companhia, com previsão de implantação para o segundo trimestre.\n\nA partir do lançamento da Trilha, serão realizados trabalhos voltados para a disseminação da Trilha e engajamento dos colaboradores, com o monitoramento mensal até o cumprimento da meta estabelecida para o mês de DEZ/2026.\n\n6 Vitrine é um termo adotado na CAIXA Loterias em que cada Unidade da Companhia informa os conhecimentos, habilidades e perfis necessários às atividades daquela área.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"19","sha256Observacao":"804945d962fdb6426415a31f460ca3afc3a7e2682b1e509080693609ce3b72d9","sha256ObservacaoSqlUtf16":"728b22e90f17e059e492b27a566ba222ea29aafd15cf0146e85d0ecadd8727f7","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-16","indicadorId":"16","lancamentoId":"183","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"A seguinte curva de meta foi definida para 2026 com relação ao presente indicador:\n▪ 1TRI26: 0%;\n▪ 2TRI26: 50% - 1ª iniciativa realizada;\n▪ 3TRI26: 50% (acumulado de 50% considerando apenas a meta do 2TRI26);\n▪ 4TRI26: 100% - 2ª iniciativa realizada.\n\nOs projetos encontram-se em fase de prospecção e estruturação, para posterior encaminhamento em rito de governança da CAIXA Loterias.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"20","sha256Observacao":"20cc0576e0386a3b76b6a8c49097ace201515ba64793599723df473dfc8dfae3","sha256ObservacaoSqlUtf16":"6eac8e249f30ba966d15ecf35b9bef59011bd22d1552359c2eef8e25f3364b1e","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"';
SET @manifesto += N'uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-17","indicadorId":"17","lancamentoId":"195","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"A meta estabelecida para o período considerou a projeção orçamentária prevista no Plano de Dispêndios Globais da Companhia de 2026.\n\nA seguinte curva de meta foi definida para 2026 com relação ao presente indicador:\n▪ 1TRI26: R$ 2.143,0 milhões;\n▪ 2TRI26: R$ 4.545,1 milhões;\n▪ 3TRI26: R$ 7.165,1 milhões;\n▪ 4TRI26: R$ 10.452,8 milhões.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"21","sha256Observacao":"5720f0c2c956096c240bf26ea6fb722bf68b8d9fe4101745eb7d8e57f4f36ae4","sha256ObservacaoSqlUtf16":"914bf850818f53fe79196c69fd48485dacc65131dcedd7007cde30e45eb80e77","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-18","indicadorId":"18","lancamentoId":"207","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"A seguinte curva de meta foi definida para 2026 com relação ao presente indicador:\n\n▪ 1º trimestre/2026: 1 elemento;\n▪ 2º trimestre/2026: 2 elementos;\n▪ 3º trimestre/2026: 5 elementos;\n▪ 4º trimestre de 2026: 10 elementos.\n\nRegistra-se que já foi concluída a instituição do Fórum de Jogo Responsável, iniciativa que materializa o elemento “Engajamento das Partes Interessadas” ao reunir representantes para, em encontros semestrais, acompanhar o Programa, colher contribuições e preocupações e promover melhorias.\n\nHá outras ações em execução, que avançam sobre os demais 9 elementos do Programa, e seu cronograma decorre de sequenciamento técnico, dependências entre entregas e cadência operacional de implementação, razão pela qual o atendimento ocorrerá em curva ao longo do exercício, conforme esperado para o período: 1 elemento no 1º trimestre; 2 elementos no 2º; 5 elementos no 3º; e 10 elementos no 4º trimestre, de forma cumulativa, mantendo a trajetória de evolução planejada do Programa.\n\nDesse modo, tem-se que o realizado cumpre o esperado para o período (1º TRI26).","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"21, 22","sha256Observacao":"1fee0674d124a0a6d1cf7ad536d861dbd993b4f5cafe833fe551c9b5835803e2","sha256ObservacaoSqlUtf16":"c58d2053df1eb484f85f3e673c23c44d666b9f2286a7bedc72d5bfb9753260eb","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea9764';
SET @manifesto += N'3aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-19","indicadorId":"19","lancamentoId":"219","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"A seguinte curva de meta foi definida para 2026 com relação ao presente indicador:\n\n▪ 1TRI26: 0%;\n▪ 2TRI26: 0,05%; (R$ 652,7 mil7);\n▪ 3TRI26: 0,10% (R$ 1.305,4 mil8 - valor acumulado, considerando o realizado do 2TRI26 e 3TRI26).\n▪ 4TRI26: 0,33% (R$ 4.307,9 mil9 - valor acumulado, considerando o realizado do 2TRI26, 3TRI26 e 4TRI26).\n\nOs projetos encontram-se em fase de prospecção e estruturação, para posterior encaminhamento em rito de governança da CAIXA Loterias.\n\n7 Valor projetado conforme orçamento 2026, que prevê Lucro Líquido em R$ 1.305,4 milhões.\n8 Valor projetado conforme orçamento 2026, que prevê Lucro Líquido em R$ 1.305,4 milhões.\n9 Valor projetado conforme orçamento 2026, que prevê Lucro Líquido em R$ 1.305,4 milhões.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"22, 23","sha256Observacao":"b6e140f4fd5a75c9bb686d965cd0d2c4d850a73c3ca4f4666ee446fec1dcd05d","sha256ObservacaoSqlUtf16":"4fe5693c065c0e83bb4a34da778b260fad567f33e46d6496aa706cbe231f5f10","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-20","indicadorId":"20","lancamentoId":"231","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"A seguinte curva de meta foi definida para 2026 com relação ao presente indicador:\n\n▪ 1 TRI26: 0%;\n▪ 2 TRI26: 50% - Publicar relatório institucional “A Sorte em Números – 2025”, consolidando dados de repasse social com linguagem acessível e foco em transparência pública.\n▪ 3 TRI26: sem meta para o período (acumulado de 50% considerando meta do 2TRI26);\n▪ 4 TRI26: 100% - Realizar campanha publicitária exclusiva com foco no repasse social das Loterias CAIXA, a ser veiculada nos canais oficiais da Companhia e demais meios estratégicos.\n\nNo 1 TRI26 foram executadas as seguintes etapas do projeto de publicação do relatório “A Sorte em Números – 2025”:\n\n▪ Planejamento e briefing da empresa de comunicação contratada pela CAIXA10;\n▪ Coleta e consolidação de conteúdo e dados com as unidades da CAIXA Loterias;\n▪ Redação do conte';
SET @manifesto += N'údo e padronização visual;\n▪ Diagramação e layout.\n\nAtualmente, o relatório “A Sorte em Números – 2025” encontra-se em fase de homologação previamente a sua publicação\n\n10 Termo de Ajuste Operacional – DEMAC.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"23, 24","sha256Observacao":"5b83643c0f14c7b33c8508f123bfd0930ab2cd8097af57bea5ebdf09117c4315","sha256ObservacaoSqlUtf16":"88d322cec6e047e651d9c6a204cf68d941eda5b4ec3c95f7126b38b3e91e7ebf","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-21","indicadorId":"21","lancamentoId":"243","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"Foi apurado que 137 funcionários, de 151 (90,7%), realizaram uma ação de disseminação de Jogo Responsável até MAR 2026, na Universidade CAIXA. As outras ações referentes ao Jogo Responsável serão realizadas no decorrer no ano de 2026.\n\nPor se tratar de objetivo a ser realizado e concluído ao longo de 2026, não há descolamento entre o percentual realizado e o esperado no 1TRI26.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"24","sha256Observacao":"c97354b6ca6604583a3ce82b9810eff86a9b6a2d73395cfb4a80f2104db9c81f","sha256ObservacaoSqlUtf16":"11be40e7ddcbe28522c2b39d4adda9ab8c4f7925540cf8e591584ca031b9d852","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-22","indicadorId":"22","lancamentoId":"255","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"Cenário com Lotex:\n\nA seguinte curva de meta foi definida para 2026, considerando o comportamento de dados do realizado de arrecadação em 2025:\n▪ 1TRI26: arrecadação via ecossistema em 1º TR/2025 representou 0,90% do total. Acrescidos 10%, a meta para o período é de 0,99%;\n▪ 2TRI26: arrecadação via ecossistema em 2TRI/2025 representou 0,78% do total. Acrescidos 10%, a meta para o período é de 0,86%;\n▪ 3TRI26: arrecadação via ecossistema em 3TRI/2025 representou 0,74% do total. Acrescidos 10%, a meta para o período é de 0,81%;\n▪ 4TRI26: arrecadação via ecossistema em 4TRI/2025 representou 0,65% do total. Acrescidos 10%, a meta para o período é de 0,72%.\n\nAo longo ';
SET @manifesto += N'do período do 1TRI26, o desempenho de vendas registrou realizado de 0,67%, representando R$ 39,8 milhões de arrecadação da Loteria Instantânea Exclusiva - Lotex, frente R$ 5.966,9 milhões de arrecadação total, com atingimento de 67,12% da meta.\nPara reversão do resultado do indicador, e em alinhamento às iniciativas estratégicas, os seguintes projetos estão sendo conduzidos com foco na ampliação de oferta da Lotex:\n\n• Programa de Afiliados Instantânea CAIXA Digital: ampliar a divulgação e a comercialização dos bilhetes da Lotex no formato digital, por meio das Unidades Lotéricas como afiliadas à plataforma oficial da CAIXA Loterias;\n• Instantânea CAIXA Compre Aqui: tem como finalidade ampliar os canais físicos de venda da Lotex, mediante a vinculação de Pontos de Venda a Unidades Lotéricas, que contribuirá para aumentar a comercialização do produto ao apostador.\n\nAdicionalmente, menciona-se que a Lotex aguarda autorização da Secretaria de Prêmios e Apostas, vinculada ao Ministério da Fazenda, sobre a prorrogação da outorga para a CAIXA Loterias continuar comercializando o produto.\nCabe destacar ainda que a meta projetada para o presente indicador considerou o lançamento de Apostas de Quota Fixa, o que não foi realizado até o presente momento, sendo necessário revisão da meta no PEI 2026-2030.\n\nCenário com Lotex e ferramenta Marketplace:\n\nA seguinte curva de meta foi definida para 2026, considerando o comportamento de dados do realizado de arrecadação em 2025, somando Lotex e Marketplace:\n▪ 1TRI26: arrecadação via ecossistema em 1º TR/2025 representou 3,42% do total. Acrescidos 10%, a meta para o período é de 3,76%;\n▪ 2TRI26: arrecadação via ecossistema em 2TRI/2025 representou 3,27% do total. Acrescidos 10%, a meta para o período é de 3,60%;\n▪ 3TRI26: arrecadação via ecossistema em 3TRI/2025 representou 3,32% do total. Acrescidos 10%, a meta para o período é de 3,65%;\n▪ 4TRI26: arrecadação via ecossistema em 4TRI/2025 representou 3,46% do total. Acrescidos 10%, a meta para o período é de 3,80%.\n\nO Marketplace de Bolões das Loterias CAIXA consiste em uma plataforma digital oficial que viabiliza a comercialização de cotas de bolões organizados pelas Unidades Lotéricas por meio dos canais eletrônicos das Loterias CAIXA, e a inclusão dos dados dessa ferramenta é aderente ao pilar estratégico Atuação em Ecossistema.\n\nAo longo do período do 1 TRI26, o desempenho de vendas na ferramenta Marketplace e dados da Lotex registrou realizado de 4,06%, representando R$ 242,3 milhões de arrecadação, frente R$ 5.966,9 milhões de arrecadação total, com atingimento de 107,94% da meta.\n\nComo estratégia no âmbito da CAIXA Loterias, menciona-se as ações previstas ao longo do ano de 2026 para a alavancagem dos resultados oriundos da ferramenta Marketplace, além dos projetos já citados para ampliação de oferta da Lotex:\n\n• Programa de Aceleração do Marketplace Lotérico: foco na segmentação das Unidades Lotéricas de acordo com o perfil de atuação, ';
SET @manifesto += N'com ações de mobilização e capacitação, para incentivo à venda de bolões no Marketplace.\n\nNo que se refere à descrição do indicador e respectiva meta, registra-se que será submetida proposta ao Conselho de Administração a fim de ajustar a meta e descrição do presente indicador, de acordo com o orçamento da Companhia de 2026, que não considera dados de Apostas de Quota Fixa.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"25, 26, 27","sha256Observacao":"9218337b3d0f501bc0b82fec9ead79f2391ab0fcef9090da552f7d2e4553c99a","sha256ObservacaoSqlUtf16":"2f6dc399303f6c64c6712fb8a76a97e46267095e93d67d61ba84107cc24d9419","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"},{"id":"observacao-documental-1tri-2026-ind-23","indicadorId":"23","lancamentoId":"267","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-03","ano":2026,"mes":3,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"A seguinte curva de meta foi definida para 2026, considerando o comportamento de dados do realizado de arrecadação em 2025:\n1TRI26: 0,50%;\n2TRI26: 1,00%;\n3TRI26: 1,50%;\n4TRI26: 2,00%.\n\nAo longo de período do 1 TRI26, a arrecadação da Rede Lotérica apresentou crescimento de 0,57%. Menciona-se que a evolução positiva reforça a efetividade inicial das ações de estímulo adotadas, ao mesmo tempo em que demonstra a necessidade de manutenção e intensificação das estratégias comerciais e operacionais, visando consolidar a recuperação e assegurar o atingimento da meta nos próximos períodos. Estratégias estruturantes do portfólio estão em andamento, como o lançamento do concurso especial alusivo à comemoração da Mega 30 anos a ser comercializado no 1º semestre/2026.","fonteDocumental":"Informe DILOT/GERIN nº 0029/2026","paginasDocumento":"27","sha256Observacao":"e9e5db2bcc3d0d6c219897c2f1983919e13750c591cbf0686741d17eebd3d7a7","sha256ObservacaoSqlUtf16":"61e9848e87addd99204aca137d5b39923846685230ae6640c7feec80886ff094","sha256DocumentoDeclarado":"5c9d14cabbb694f8dd5bea97643aff9b79e7c37f16f1a7fb489ee9ec1edfb068","sha256ArquivoFisico":"9f3e66e2d529a1a66cc7ad842ebc5430171a60de99cb64077b7236613ce9b08c","documentoReferencia":"uploads/evidencias/630106a38f59b219bdbc68e93d9609995eefdf93dcc9a232.pdf","origemRegistro":"20261027_003_observacoes_documentais_1tri_2026.sql"}]';
  IF ISJSON(@manifesto)<>1 THROW 53402,N'Manifesto incorporado invalido.',1;

  DECLARE @carga TABLE(
    id NVARCHAR(100) PRIMARY KEY,lancamento_id NVARCHAR(100),indicador_id NVARCHAR(100),competencia NVARCHAR(40),
    ano INT,mes INT,versao_lancamento INT,status_esperado NVARCHAR(100),tipo_observacao NVARCHAR(100),observacao NVARCHAR(MAX),
    fonte_documental NVARCHAR(500),paginas_documento NVARCHAR(100),sha256_observacao CHAR(64),
    sha256_observacao_sql_utf16 CHAR(64),sha256_documento_declarado CHAR(64),sha256_arquivo_fisico CHAR(64),
    documento_referencia NVARCHAR(500),origem_registro NVARCHAR(255)
  );
  INSERT @carga
  SELECT id,lancamentoId,indicadorId,competencia,ano,mes,versaoLancamento,statusEsperado,tipoObservacao,observacao,
         fonteDocumental,paginasDocumento,sha256Observacao,sha256ObservacaoSqlUtf16,sha256DocumentoDeclarado,
         sha256ArquivoFisico,documentoReferencia,origemRegistro
  FROM OPENJSON(@manifesto) WITH(
    id NVARCHAR(100) '$.id',lancamentoId NVARCHAR(100) '$.lancamentoId',indicadorId NVARCHAR(100) '$.indicadorId',
    competencia NVARCHAR(40) '$.competencia',ano INT '$.ano',mes INT '$.mes',versaoLancamento INT '$.versaoLancamento',
    statusEsperado NVARCHAR(100) '$.statusEsperado',tipoObservacao NVARCHAR(100) '$.tipoObservacao',
    observacao NVARCHAR(MAX) '$.observacao',fonteDocumental NVARCHAR(500) '$.fonteDocumental',
    paginasDocumento NVARCHAR(100) '$.paginasDocumento',sha256Observacao CHAR(64) '$.sha256Observacao',
    sha256ObservacaoSqlUtf16 CHAR(64) '$.sha256ObservacaoSqlUtf16',sha256DocumentoDeclarado CHAR(64) '$.sha256DocumentoDeclarado',
    sha256ArquivoFisico CHAR(64) '$.sha256ArquivoFisico',documentoReferencia NVARCHAR(500) '$.documentoReferencia',
    origemRegistro NVARCHAR(255) '$.origemRegistro'
  );

  IF (SELECT COUNT(*) FROM @carga)<>23 OR (SELECT COUNT(DISTINCT indicador_id) FROM @carga)<>23
    THROW 53403,N'Manifesto deve conter exatamente os 23 indicadores.',1;
  IF EXISTS(SELECT 1 FROM @carga WHERE tipo_observacao<>@tipo OR competencia<>N'2026-03' OR ano<>2026 OR mes<>3 OR origem_registro<>@migration)
    THROW 53404,N'Identidade documental da carga invalida.',1;
  DECLARE @existentes INT=(SELECT COUNT(*) FROM dbo.lancamentos_observacoes_documentais WHERE origem_registro=@migration);
  IF @existentes NOT IN(0,23) THROW 53407,N'Aplicacao parcial detectada; nenhuma linha sera acrescentada.',1;
  IF @existentes=0 AND EXISTS(
    SELECT 1 FROM @carga c
    LEFT JOIN dbo.lancamentos l ON l.id=c.lancamento_id AND l.indicador_id=c.indicador_id
      AND l.competencia=c.competencia AND l.ano=c.ano AND l.mes=c.mes
      AND l.versao_atual=c.versao_lancamento AND l.status=c.status_esperado
    WHERE l.id IS NULL
  ) THROW 53405,N'Lancamento, competencia, versao ou status divergiu do manifesto.',1;
  IF EXISTS(
    SELECT 1 FROM @carga
    WHERE LOWER(CONVERT(VARCHAR(64),HASHBYTES('SHA2_256',CONVERT(VARBINARY(MAX),observacao)),2))<>sha256_observacao_sql_utf16
  ) THROW 53406,N'Hash SQL UTF-16 da observacao literal divergente.',1;

  IF @existentes=23 AND EXISTS(
    SELECT 1 FROM @carga c FULL JOIN (
      SELECT * FROM dbo.lancamentos_observacoes_documentais WHERE origem_registro=@migration
    ) d ON d.id=c.id
    WHERE c.id IS NULL OR d.id IS NULL OR d.lancamento_id<>c.lancamento_id OR d.indicador_id<>c.indicador_id
      OR d.competencia<>c.competencia OR d.ano<>c.ano OR d.mes<>c.mes OR d.versao_lancamento<>c.versao_lancamento
      OR d.tipo_observacao<>c.tipo_observacao OR d.observacao<>c.observacao OR d.fonte_documental<>c.fonte_documental
      OR d.paginas_documento<>c.paginas_documento OR d.sha256_observacao<>c.sha256_observacao
      OR d.sha256_documento_declarado<>c.sha256_documento_declarado OR d.sha256_arquivo_fisico<>c.sha256_arquivo_fisico
      OR d.documento_referencia<>c.documento_referencia OR d.substitui_observacao_id IS NOT NULL
  ) THROW 53408,N'Reexecucao encontrou conteudo documental divergente.',1;
  IF @existentes=0 AND EXISTS(
    SELECT 1 FROM @carga c JOIN dbo.lancamentos_observacoes_documentais d
      ON d.id=c.id OR (d.lancamento_id=c.lancamento_id AND d.versao_lancamento=c.versao_lancamento
      AND d.competencia=c.competencia AND d.tipo_observacao=c.tipo_observacao
      AND d.sha256_documento_declarado=c.sha256_documento_declarado)
  ) THROW 53409,N'Conflito com carga documental preexistente.',1;

  DECLARE @lancamentos_antes TABLE(id NVARCHAR(100) PRIMARY KEY,fingerprint VARBINARY(32));
  INSERT @lancamentos_antes
  SELECT l.id,HASHBYTES('SHA2_256',CONVERT(VARBINARY(MAX),
    CAST(N'' AS NVARCHAR(MAX))+ISNULL(l.id,N'<NULL>')+N'|'+ISNULL(l.indicador_id,N'<NULL>')+N'|'+ISNULL(l.competencia,N'<NULL>')+
    N'|'+ISNULL(CONVERT(NVARCHAR(20),l.ano),N'<NULL>')+N'|'+ISNULL(CONVERT(NVARCHAR(20),l.mes),N'<NULL>')+
    N'|'+ISNULL(l.trimestre,N'<NULL>')+N'|'+ISNULL(l.plano,N'<NULL>')+N'|'+ISNULL(l.pilar,N'<NULL>')+
    N'|'+ISNULL(l.unidade_apuradora,N'<NULL>')+N'|'+ISNULL(l.diretoria_responsavel,N'<NULL>')+
    N'|'+ISNULL(l.dados_entrada_json,N'<NULL>')+N'|'+ISNULL(l.resultado_calculado,N'<NULL>')+
    N'|'+ISNULL(l.resultado_oficial,N'<NULL>')+N'|'+ISNULL(l.meta_referencia,N'<NULL>')+
    N'|'+ISNULL(l.percentual_atingido,N'<NULL>')+N'|'+ISNULL(l.situacao,N'<NULL>')+N'|'+ISNULL(l.status,N'<NULL>')+
    N'|'+ISNULL(l.observacao_unidade,N'<NULL>')+N'|'+ISNULL(l.referencia_evidencia,N'<NULL>')+
    N'|'+ISNULL(l.evidencia_id,N'<NULL>')+N'|'+CONVERT(NVARCHAR(20),l.versao_atual)+
    N'|'+ISNULL(l.usuario_responsavel,N'<NULL>')+N'|'+ISNULL(l.created_at,N'<NULL>')+N'|'+ISNULL(l.updated_at,N'<NULL>')
  )) FROM dbo.lancamentos l JOIN @carga c ON c.lancamento_id=l.id;

  DECLARE @homologacoesAntes NVARCHAR(MAX)=(SELECT h.* FROM dbo.homologacoes h JOIN @carga c ON c.lancamento_id=h.lancamento_id ORDER BY h.id FOR JSON PATH,INCLUDE_NULL_VALUES);
  DECLARE @evidenciasAntes NVARCHAR(MAX)=(SELECT e.* FROM dbo.evidencias e JOIN @carga c ON c.lancamento_id=e.lancamento_id ORDER BY e.id FOR JSON PATH,INCLUDE_NULL_VALUES);
  DECLARE @retificacoesAntes NVARCHAR(MAX)=(SELECT r.* FROM dbo.retificacoes r JOIN @carga c ON c.lancamento_id=r.lancamento_id ORDER BY r.id FOR JSON PATH,INCLUDE_NULL_VALUES);
  DECLARE @reaberturasAntes NVARCHAR(MAX)=(SELECT s.* FROM dbo.solicitacoes_reabertura s JOIN @carga c ON c.lancamento_id=s.lancamento_id ORDER BY s.id FOR JSON PATH,INCLUDE_NULL_VALUES);
  DECLARE @auditoriaAntes NVARCHAR(MAX)=(SELECT a.* FROM dbo.auditoria a JOIN @carga c ON c.lancamento_id=a.entidade_id WHERE a.entidade=N'lancamentos' ORDER BY a.id FOR JSON PATH,INCLUDE_NULL_VALUES);

  IF @existentes=0
  BEGIN
    INSERT dbo.lancamentos_observacoes_documentais(
      id,lancamento_id,indicador_id,competencia,ano,mes,versao_lancamento,tipo_observacao,observacao,
      fonte_documental,paginas_documento,sha256_observacao,sha256_documento_declarado,sha256_arquivo_fisico,
      documento_referencia,substitui_observacao_id,origem_registro
    )
    SELECT id,lancamento_id,indicador_id,competencia,ano,mes,versao_lancamento,tipo_observacao,observacao,
      fonte_documental,paginas_documento,sha256_observacao,sha256_documento_declarado,sha256_arquivo_fisico,
      documento_referencia,NULL,origem_registro FROM @carga;
    SET @linhasInseridas=@@ROWCOUNT;
    IF @linhasInseridas<>23 THROW 53410,N'Quantidade inserida diferente de 23.',1;
  END

  IF EXISTS(
    SELECT 1 FROM @lancamentos_antes a JOIN dbo.lancamentos l ON l.id=a.id
    WHERE a.fingerprint<>HASHBYTES('SHA2_256',CONVERT(VARBINARY(MAX),
      CAST(N'' AS NVARCHAR(MAX))+ISNULL(l.id,N'<NULL>')+N'|'+ISNULL(l.indicador_id,N'<NULL>')+N'|'+ISNULL(l.competencia,N'<NULL>')+
      N'|'+ISNULL(CONVERT(NVARCHAR(20),l.ano),N'<NULL>')+N'|'+ISNULL(CONVERT(NVARCHAR(20),l.mes),N'<NULL>')+
      N'|'+ISNULL(l.trimestre,N'<NULL>')+N'|'+ISNULL(l.plano,N'<NULL>')+N'|'+ISNULL(l.pilar,N'<NULL>')+
      N'|'+ISNULL(l.unidade_apuradora,N'<NULL>')+N'|'+ISNULL(l.diretoria_responsavel,N'<NULL>')+
      N'|'+ISNULL(l.dados_entrada_json,N'<NULL>')+N'|'+ISNULL(l.resultado_calculado,N'<NULL>')+
      N'|'+ISNULL(l.resultado_oficial,N'<NULL>')+N'|'+ISNULL(l.meta_referencia,N'<NULL>')+
      N'|'+ISNULL(l.percentual_atingido,N'<NULL>')+N'|'+ISNULL(l.situacao,N'<NULL>')+N'|'+ISNULL(l.status,N'<NULL>')+
      N'|'+ISNULL(l.observacao_unidade,N'<NULL>')+N'|'+ISNULL(l.referencia_evidencia,N'<NULL>')+
      N'|'+ISNULL(l.evidencia_id,N'<NULL>')+N'|'+CONVERT(NVARCHAR(20),l.versao_atual)+
      N'|'+ISNULL(l.usuario_responsavel,N'<NULL>')+N'|'+ISNULL(l.created_at,N'<NULL>')+N'|'+ISNULL(l.updated_at,N'<NULL>')
    ))
  ) THROW 53411,N'Snapshot historico de lancamento foi alterado.',1;
  IF @homologacoesAntes<>(SELECT h.* FROM dbo.homologacoes h JOIN @carga c ON c.lancamento_id=h.lancamento_id ORDER BY h.id FOR JSON PATH,INCLUDE_NULL_VALUES)
    OR @evidenciasAntes<>(SELECT e.* FROM dbo.evidencias e JOIN @carga c ON c.lancamento_id=e.lancamento_id ORDER BY e.id FOR JSON PATH,INCLUDE_NULL_VALUES)
    OR @retificacoesAntes<>(SELECT r.* FROM dbo.retificacoes r JOIN @carga c ON c.lancamento_id=r.lancamento_id ORDER BY r.id FOR JSON PATH,INCLUDE_NULL_VALUES)
    OR @reaberturasAntes<>(SELECT s.* FROM dbo.solicitacoes_reabertura s JOIN @carga c ON c.lancamento_id=s.lancamento_id ORDER BY s.id FOR JSON PATH,INCLUDE_NULL_VALUES)
    OR @auditoriaAntes<>(SELECT a.* FROM dbo.auditoria a JOIN @carga c ON c.lancamento_id=a.entidade_id WHERE a.entidade=N'lancamentos' ORDER BY a.id FOR JSON PATH,INCLUDE_NULL_VALUES)
    THROW 53412,N'Governanca ou auditoria historica foi alterada.',1;

  IF (SELECT COUNT(*) FROM dbo.lancamentos_observacoes_documentais WHERE origem_registro=@migration)<>23
    THROW 53413,N'Pos-condicao documental incompleta.',1;

  IF @transacaoPropria=1 COMMIT TRANSACTION;
  SELECT N'COMMIT' AS transacao,@linhasInseridas AS registros_criados,0 AS registros_alterados,0 AS registros_removidos,
    CASE WHEN @existentes=23 THEN N'JA APLICADA - SEM DML' ELSE N'23 OBSERVACOES DOCUMENTAIS CRIADAS' END AS resultado;
END TRY
BEGIN CATCH
  IF @transacaoPropria=1 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
  THROW;
END CATCH;

